    const values=Array.isArray(input.values)?input.values.map(Number).filter(Number.isFinite):[Number(input.value||0)];
    const sample=values.slice(-9);
    const n=sample.length||1;
    const mean=sample.reduce((a,b)=>a+b,0)/n;
    const variance=sample.reduce((a,b)=>a+(b-mean)**2,0)/n;
    const deviation=Math.sqrt(variance);
    const latest=sample[n-1]||0;
